mapper.select:
SELECT id, tenant_id, program_id, member_id, identity_type, identity_source,
       identity_value, normalized_value, verified, is_primary, status,
       effective_from, effective_to, created_at, updated_at
FROM loyalty.member_identity
WHERE program_id = #{programId}
  AND identity_type = #{type}
  AND identity_source = #{source}
  AND normalized_value = #{normalized}
  AND status = 'ACTIVE'
